209	      let response: Response | null = null;
210	      // Mirrors the POC's `bubble` variable: non-null once `meta` has arrived,
211	      // which is how we know whether a failure should replace the turn or sit
212	      // underneath a partial answer.
213	      let started = false;
214	      let answered = '';
215	
216	      try {
217	        response = await fetch(`${api}/chat`, {
218	          method: 'POST',
219	          headers: {
220	            'Content-Type': 'application/json',
221	            // Asking for the streamed form. Drop this header and the same
222	            // route returns one JSON body instead (D-019).
223	            Accept: 'text/event-stream',
224	          },
225	          body: JSON.stringify({ conversationId: conversationId.current, message: text }),
226	        });
227	        // Validation errors still arrive as a normal status, because they
228	        // happen before any streaming starts.
229	        if (!response.ok) throw new Error('request failed');
230	
231	        let streamError: string | null = null;
232	        // The server ends every successful answer with `done`. Without checking
233	        // for it, ANY end of stream looks like success — including the server
234	        // dying or the socket dropping mid-sentence, which would leave a
235	        // truncated answer on screen indistinguishable from a complete one.
236	        let sawDone = false;
237	
238	        await readEventStream(response, (event, data) => {
239	          if (event === 'meta') {
240	            conversationId.current = data.conversationId;
241	            started = true;
242	            // Swapped in the moment retrieval finishes, before a single token
243	            // of the answer exists — so the sources panel appears first and you
244	            // can read what the model was given while it is still deciding what
245	            // to make of it (D-019).
246	            setTurns((prev) =>
247	              prev.map((turn) =>
248	                turn.id === replyId
249	                  ? {
250	                      id: replyId,
251	                      kind: 'answer',
252	                      text: '',
253	                      // Absent for a guest (D-140): the route removed the keys, so a missing list means "not shown", never "none".
254	                      sources: Array.isArray(data.sources) ? data.sources : null,
255	                      toolCalls: [],
256	                      roomCards: data.roomCards,
257	                      roomCardsView: data.roomCardsView,
258	                      searchQuery: typeof data.searchQuery === 'string' ? data.searchQuery : '',
259	                      question: text,
260	                    }
261	                  : turn,
262	              ),
263	            );
264	          } else if (event === 'delta') {
265	            answered += data.text;
266	            setTurns((prev) =>
267	              prev.map((turn) =>
268	                turn.id === replyId && turn.kind === 'answer'
269	                  ? { ...turn, text: turn.text + data.text }
270	                  : turn,
271	              ),
272	            );
273	          } else if (event === 'tool') {
274	            // A tool call finished. It arrives after `meta` and before the
275	            // answer written from it, so the reader can see what was checked
276	            // while the answer is still being written, the same way sources
277	            // arrive first (D-019, D-037).
278	            setTurns((prev) =>
279	              prev.map((turn) =>
280	                turn.id === replyId && turn.kind === 'answer'
281	                  ? { ...turn, toolCalls: [...turn.toolCalls, data as ToolCallRecord] }
282	                  : turn,
283	              ),
284	            );
285	          } else if (event === 'done') {
286	            sawDone = true;
287	          } else if (event === 'error') {
