  event.preventDefault();
  // Enter in a field submits the form: before the review, that is Continue.
  if (step < 3) {
    if (missing[step] === '') go(step + 1);
    return;
  }
  setError(null);
  setSending(true);
  try {
    const response = await fetch(`${api}/book/request`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ slotId, rooms, checkIn, nights: nightCount, name, phone, email, notes: notes || null, website, promoCode: promoCode.trim() || null, consent, consentVersion: policyVersion }),
    });
    const body = await response.json().catch(() => null);
    if (!response.ok) {
      setError(body?.error ?? `The request could not be sent (${response.status}).`);
      return;
    }
    setSent({ receipt: body as RequestReceipt });
    window.scrollTo({ top: 0 });
  } catch {
    setError('Could not reach the server. Please try again.');
  } finally {
    setSending(false);
  }
}

function startOver() {
  setSent(null);
  setCopied(false);
